(() => {
  'use strict';
  // Keep the appendix available when opened directly by a shared fragment URL.
  const revealFragment = () => {
    let target;
    try { target = document.getElementById(decodeURIComponent(location.hash.slice(1))); } catch { return; }
    if (!target) return;
    for (let ancestor = target; ancestor; ancestor = ancestor.parentElement) {
      if (ancestor.tagName === 'DETAILS') ancestor.open = true;
      ancestor.classList.remove('is-pending');
    }
  };
  revealFragment();
  addEventListener('hashchange', revealFragment);
})();


(() => {
  'use strict';
  document.querySelectorAll('[data-document-mode]').forEach(button => {
    button.addEventListener('click', () => {
      const article=button.closest('.archive-document');
      const comparing=button.dataset.documentMode==='compare';
      article.classList.toggle('is-document-comparing',comparing);
      article.querySelectorAll('[data-document-mode]').forEach(control => control.setAttribute('aria-pressed',String(control===button)));
      // On a narrow page the expanded original sits above the controls.
      if(comparing&&matchMedia('(max-width:700px)').matches){
        article.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});
      }
    });
  });
})();
